-- ── admin_get_activity_log(text,integer,integer) ────────────────
CREATE OR REPLACE FUNCTION public.admin_get_activity_log(p_caller text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, entity_type text, entity_id text, action text, actor_uid text, actor_role text, actor_name text, actor_email text, diff jsonb, note text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN

  perform assert_verified_admin(p_caller);  -- P0.5
  IF NOT EXISTS (
    SELECT 1 FROM admins WHERE uid = p_caller AND is_active = true
  ) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  RETURN QUERY
    SELECT c.id, c.entity_type, c.entity_id, c.action,
           c.actor_uid, c.actor_role,
           a.name  AS actor_name,
           a.email AS actor_email,
           c.diff, c.note, c.created_at
      FROM changelog c
      LEFT JOIN admins a ON a.uid = c.actor_uid
     ORDER BY c.created_at DESC
     LIMIT p_limit
    OFFSET p_offset;
END;
$function$;

-- ── admin_get_coaching_centre_count(text) ───────────────────────
CREATE OR REPLACE FUNCTION public.admin_get_coaching_centre_count(p_caller text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text; v_count bigint;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  select role into v_role from admins where uid = p_caller and is_active = true;
  if v_role is null or v_role not in ('superadmin','admin') then raise exception 'Access denied'; end if;
  select count(*) into v_count from coaching_centres;
  return v_count;
end; $function$;

