-- ── admin_get_top_misconceptions(text,integer,integer) ──────────
CREATE OR REPLACE FUNCTION public.admin_get_top_misconceptions(p_caller text, p_days integer DEFAULT 7, p_limit integer DEFAULT 20)
 RETURNS TABLE(subject text, chapter text, distractor text, correct_answer text, question_text text, total_occurrences bigint, distinct_students bigint, last_seen_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text;
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  select role into v_role from admins where uid = p_caller and is_active = true;
  if v_role is null or v_role not in ('superadmin','admin') then
    raise exception 'Access denied';
  end if;

  return query
  select
    m.subject, m.chapter, m.distractor, m.correct_answer, m.question_text,
    sum(m.count)                as total_occurrences,
    count(distinct m.user_id)   as distinct_students,
    max(m.last_seen_at)         as last_seen_at
  from public.concept_misconceptions m
  where m.last_seen_at >= now() - (p_days || ' days')::interval
  group by m.subject, m.chapter, m.distractor, m.correct_answer, m.question_text
  order by total_occurrences desc, last_seen_at desc
  limit p_limit;
end;
$function$;

