-- ── admin_list(text) ────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.admin_list(p_caller text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  SELECT role INTO v_role FROM admins WHERE uid = p_caller AND is_active = true;
  IF v_role IS DISTINCT FROM 'superadmin' THEN
    RETURN json_build_object('error', 'Unauthorized');
  END IF;
  RETURN (
    SELECT json_agg(row_to_json(a))
    FROM (SELECT uid, email, name, role, is_active, added_by, created_at, updated_at
          FROM admins ORDER BY created_at) a
  );
END;
$function$;

-- ── admin_search_published_tests(text,text,integer) ─────────────
CREATE OR REPLACE FUNCTION public.admin_search_published_tests(p_caller text, p_query text, p_limit integer DEFAULT 5)
 RETURNS SETOF published_tests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_term text := '%' || coalesce(p_query, '') || '%';
begin
  perform assert_verified_admin(p_caller);  -- P0.5
  if not public.is_active_admin(p_caller) then
    raise exception 'Access denied';
  end if;
  return query
    select * from public.published_tests
    where title ilike v_term
       or subject ilike v_term
       or exam_type ilike v_term
    order by created_at desc
    limit p_limit;
end;
$function$;

-- ── coaching_admin_list(text) ───────────────────────────────────
CREATE OR REPLACE FUNCTION public.coaching_admin_list(p_caller text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  caller_role TEXT;
  caller_centre UUID;
  result JSON;
BEGIN
  perform assert_verified_admin(p_caller);  -- P0.5
  -- Check if caller is superadmin
  SELECT role INTO caller_role FROM admins WHERE uid = p_caller LIMIT 1;

  IF caller_role IN ('superadmin','admin') THEN
    SELECT json_agg(r) INTO result
    FROM (
      SELECT ca.*, cc.name AS centre_name
      FROM coaching_admins ca
      JOIN coaching_centres cc ON cc.id = ca.centre_id
      ORDER BY ca.created_at DESC
    ) r;
  ELSE
    -- Check if caller is centre_admin
    SELECT centre_id INTO caller_centre
    FROM coaching_admins WHERE uid = p_caller AND role = 'centre_admin' AND is_active = true LIMIT 1;

    IF caller_centre IS NULL THEN
      RAISE EXCEPTION 'Access denied';
    END IF;

    SELECT json_agg(r) INTO result
    FROM (
      SELECT ca.*, cc.name AS centre_name
      FROM coaching_admins ca
      JOIN coaching_centres cc ON cc.id = ca.centre_id
      WHERE ca.centre_id = caller_centre
      ORDER BY ca.created_at DESC
    ) r;
  END IF;

  RETURN COALESCE(result, '[]'::json);
END;
$function$;

commit;
